{
  "name": "jsinspect",
  "version": "0.12.7",
  "description": "Detect structural similarities in your code",
  "keywords": [
    "inspect",
    "detect",
    "code",
    "duplicate",
    "structure",
    "copy",
    "paste"
  ],
  "author": "Daniel St. Jules <danielst.jules@gmail.com>",
