  },
  "dependencies": {
    "babylon": "6.16.1",
    "chalk": "^2.1.0",
    "commander": "^2.11.0",
    "filepaths": "0.3.0",
    "stable": "^0.1.6",
    "strip-indent": "^1.0.1",
    "strip-json-comments": "1.0.2"
  },
  "devDependencies": {
    "concat-stream": "^1.5.0",
